import logging

import torch
import triton
import triton.language as tl

from flag_gems import runtime
from flag_gems.runtime import torch_device_fn

logger = logging.getLogger(__name__)

_NUM_SPC = 48
_SMALL_NUMEL = 131072
_FLAT_COPY_BLOCK = 8192
_TILE_MAX = 128
_TILE_WARPS = 1
_PAIR_TILES = 128
_PAIR_TILES_WIDE = 64


@triton.autotune(configs=runtime.get_tuned_config("rot90"), key=["n_elements"])
@triton.jit
def rot90_kernel_2d(
    in_ptr,
    out_ptr,
    n_elements,
    M,
    N,
    k_norm,
    BLOCK_SIZE: tl.constexpr,
):
    """
    rot90 kernel for rotating a tensor by 90 degrees in the plane [0, 1].

    Input shape: [M, N, D2, D3, ...]
    Output shape for k=1,3: [N, M, D2, D3, ...]
    Output shape for k=0,2: [M, N, D2, D3, ...]

    Formulas (verified):
    - k=0 (identity): out[i,j] = in[i,j] -> in_dim0=out_dim0, in_dim1=out_dim1
    - k=1 (90° clockwise): out[i,j] = in[j, N-1-i]
      -> in_dim0=out_dim1, in_dim1=N-1-out_dim0
    - k=2 (180°): out[i,j] = in[M-1-i, N-1-j]
      -> in_dim0=M-1-out_dim0, in_dim1=N-1-out_dim1
    - k=3 (270° clockwise / 90° CCW): out[i,j] = in[M-1-j, i]
      -> in_dim0=M-1-out_dim1, in_dim1=out_dim0
    """
    pid = tl.program_id(axis=0)
    block_start = pid * BLOCK_SIZE
    offsets = block_start + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements

    m_minus_1 = M - 1
    n_minus_1 = N - 1

    if k_norm == 0:
        # Identity case - output same shape as input [M, N, ...]
        stride_0 = n_elements // M
        out_dim0 = offsets // stride_0
        remainder = offsets % stride_0
        out_dim1 = remainder % N

        in_dim0 = out_dim0
        in_dim1 = out_dim1

        stride_0_in = n_elements // M
        in_offset = in_dim0 * stride_0_in + in_dim1 * (stride_0_in // N)

    elif k_norm == 1:
        # 90° clockwise - output shape [N, M, ...]
        stride_0 = n_elements // N
        out_dim0 = offsets // stride_0
        remainder = offsets % stride_0
        out_dim1 = remainder % M

        # out[i,j] = in[j, N-1-i] where i=out_dim0, j=out_dim1
        in_dim0 = out_dim1
        in_dim1 = n_minus_1 - out_dim0

        stride_0_in = n_elements // M
        in_offset = in_dim0 * stride_0_in + in_dim1 * (stride_0_in // N)

    elif k_norm == 2:
        # 180° - output same shape as input [M, N, ...]
        stride_0 = n_elements // M
        out_dim0 = offsets // stride_0
        remainder = offsets % stride_0
        out_dim1 = remainder % N

        # out[i,j] = in[M-1-i, N-1-j]
        in_dim0 = m_minus_1 - out_dim0
        in_dim1 = n_minus_1 - out_dim1

        stride_0_in = n_elements // M
        in_offset = in_dim0 * stride_0_in + in_dim1 * (stride_0_in // N)

    else:  # k_norm == 3
        # 270° clockwise - output shape [N, M, ...]
        stride_0 = n_elements // N
        out_dim0 = offsets // stride_0
        remainder = offsets % stride_0
        out_dim1 = remainder % M

        # out[i,j] = in[M-1-j, i]
        in_dim0 = m_minus_1 - out_dim1
        in_dim1 = out_dim0

        stride_0_in = n_elements // M
        in_offset = in_dim0 * stride_0_in + in_dim1 * (stride_0_in // N)

    x = tl.load(in_ptr + in_offset, mask=mask)
    tl.store(out_ptr + offsets, x, mask=mask)


@triton.jit
def _rot90_flat_copy_kernel(
    in_ptr,
    out_ptr,
    n_elements,
    BLOCK: tl.constexpr,
    EVEN: tl.constexpr,
):
    # k=0: identity permutation, contiguous on both sides.
    pid = tl.program_id(0)
    num_ctas = tl.num_programs(0)
    num_tiles = tl.cdiv(n_elements, BLOCK)
    for tile in range(pid, num_tiles, num_ctas):
        offs = tile * BLOCK + tl.arange(0, BLOCK)
        if EVEN:
            v = tl.load(in_ptr + offs)
            tl.store(out_ptr + offs, v)
        else:
            m = offs < n_elements
            v = tl.load(in_ptr + offs, mask=m)
            tl.store(out_ptr + offs, v, mask=m)


@triton.jit
def _rot90_k1_tile_kernel(
    in_ptr,
    out_ptr,
    M,
    N,
    num_c_tiles,
    num_tiles,
    BLOCK_R: tl.constexpr,
    BLOCK_C: tl.constexpr,
    U: tl.constexpr,
):
    # out[i, j] = in[j, N-1-i], out shape [N, M].  DMA-form load via a 2D
    # block pointer with positive strides (N, 1); the raw store absorbs the
    # row reversal with a -M stride on dim0 while its fast dim ascends.
    pid = tl.program_id(0)
    num_ctas = tl.num_programs(0)
    ir = tl.arange(0, BLOCK_R)
    ic = tl.arange(0, BLOCK_C)
    t_last = num_tiles - 1
    GU = num_ctas * U
    for t0 in range(pid * U, num_tiles, GU):
        ta = tl.minimum(t0, t_last)
        rta = ta // num_c_tiles
        cta = ta - rta * num_c_tiles
        r0a = tl.minimum(rta * BLOCK_R, N - BLOCK_R)
        c0a = tl.minimum(cta * BLOCK_C, M - BLOCK_C)
        src_a = tl.make_block_ptr(
            in_ptr,
            (M, N),
            (N, 1),
            (c0a, N - BLOCK_R - r0a),
            (BLOCK_C, BLOCK_R),
            (1, 0),
        )
        va = tl.load(src_a)
        if U == 2:
            tb = tl.minimum(t0 + 1, t_last)
            rtb = tb // num_c_tiles
            ctb = tb - rtb * num_c_tiles
            r0b = tl.minimum(rtb * BLOCK_R, N - BLOCK_R)
            c0b = tl.minimum(ctb * BLOCK_C, M - BLOCK_C)
            src_b = tl.make_block_ptr(
                in_ptr,
                (M, N),
                (N, 1),
                (c0b, N - BLOCK_R - r0b),
                (BLOCK_C, BLOCK_R),
                (1, 0),
            )
            vb = tl.load(src_b)
        tl.store(
            out_ptr + (r0a + BLOCK_R - 1 - ir)[:, None] * M + (c0a + ic)[None, :],
            tl.trans(va),
        )
        if U == 2:
            tl.store(
                out_ptr + (r0b + BLOCK_R - 1 - ir)[:, None] * M + (c0b + ic)[None, :],
                tl.trans(vb),
            )


@triton.jit
def _rot90_k2_tile_kernel(
    in_ptr,
    out_ptr,
    M,
    N,
    num_c_tiles,
    num_tiles,
    BLOCK_R: tl.constexpr,
    BLOCK_C: tl.constexpr,
    U: tl.constexpr,
):
    # out[i, j] = in[M-1-i, N-1-j], out shape [M, N].  Descending fast-dim
    # raw load + ascending raw store, same orientation, no transpose.
    pid = tl.program_id(0)
    num_ctas = tl.num_programs(0)
    ir = tl.arange(0, BLOCK_R)
    ic = tl.arange(0, BLOCK_C)
    t_last = num_tiles - 1
    GU = num_ctas * U
    for t0 in range(pid * U, num_tiles, GU):
        ta = tl.minimum(t0, t_last)
        rta = ta // num_c_tiles
        cta = ta - rta * num_c_tiles
        r0a = tl.minimum(rta * BLOCK_R, M - BLOCK_R)
        c0a = tl.minimum(cta * BLOCK_C, N - BLOCK_C)
        va = tl.load(
            in_ptr + (M - 1 - (r0a + ir))[:, None] * N + (N - 1 - (c0a + ic))[None, :]
        )
        if U == 2:
            tb = tl.minimum(t0 + 1, t_last)
            rtb = tb // num_c_tiles
            ctb = tb - rtb * num_c_tiles
            r0b = tl.minimum(rtb * BLOCK_R, M - BLOCK_R)
            c0b = tl.minimum(ctb * BLOCK_C, N - BLOCK_C)
            vb = tl.load(
                in_ptr
                + (M - 1 - (r0b + ir))[:, None] * N
                + (N - 1 - (c0b + ic))[None, :]
            )
        tl.store(out_ptr + (r0a + ir)[:, None] * N + (c0a + ic)[None, :], va)
        if U == 2:
            tl.store(out_ptr + (r0b + ir)[:, None] * N + (c0b + ic)[None, :], vb)


@triton.jit
def _rot90_k3_tile_kernel(
    in_ptr,
    out_ptr,
    M,
    N,
    num_c_tiles,
    num_tiles,
    BLOCK_R: tl.constexpr,
    BLOCK_C: tl.constexpr,
    U: tl.constexpr,
):
    # out[i, j] = in[M-1-j, i], out shape [N, M].  Raw load [BLOCK_C,
    # BLOCK_R] with an ascending fast dim, tl.trans, then a positive-stride
    # block-pointer store.
    pid = tl.program_id(0)
    num_ctas = tl.num_programs(0)
    ir = tl.arange(0, BLOCK_R)
    ic = tl.arange(0, BLOCK_C)
    t_last = num_tiles - 1
    GU = num_ctas * U
    for t0 in range(pid * U, num_tiles, GU):
        ta = tl.minimum(t0, t_last)
        rta = ta // num_c_tiles
        cta = ta - rta * num_c_tiles
        r0a = tl.minimum(rta * BLOCK_R, N - BLOCK_R)
        c0a = tl.minimum(cta * BLOCK_C, M - BLOCK_C)
        va = tl.load(in_ptr + (M - 1 - (c0a + ic))[:, None] * N + (r0a + ir)[None, :])
        if U == 2:
            tb = tl.minimum(t0 + 1, t_last)
            rtb = tb // num_c_tiles
            ctb = tb - rtb * num_c_tiles
            r0b = tl.minimum(rtb * BLOCK_R, N - BLOCK_R)
            c0b = tl.minimum(ctb * BLOCK_C, M - BLOCK_C)
            vb = tl.load(
                in_ptr + (M - 1 - (c0b + ic))[:, None] * N + (r0b + ir)[None, :]
            )
        dst_a = tl.make_block_ptr(
            out_ptr, (N, M), (M, 1), (r0a, c0a), (BLOCK_R, BLOCK_C), (1, 0)
        )
        tl.store(dst_a, tl.trans(va))
        if U == 2:
            dst_b = tl.make_block_ptr(
                out_ptr, (N, M), (M, 1), (r0b, c0b), (BLOCK_R, BLOCK_C), (1, 0)
            )
            tl.store(dst_b, tl.trans(vb))


def _prev_pow2(value):
    block = _TILE_MAX
    while block > value:
        block //= 2
    return block


def _launch_tiled(inp, out, k_norm, M, N):
    if k_norm == 2:
        r_dim, c_dim = M, N
    else:
        r_dim, c_dim = N, M
    block_r = min(_TILE_MAX, _prev_pow2(r_dim))
    block_c = min(_TILE_MAX, _prev_pow2(c_dim))
    num_r_tiles = triton.cdiv(r_dim, block_r)
    num_c_tiles = triton.cdiv(c_dim, block_c)
    num_tiles = num_r_tiles * num_c_tiles
    # pair tiles per program only where it won the sweep: 2048^2-class
    # grids, and 1024^2-class grids for 4-byte dtypes (fp32); anywhere else
    # the halved grid costs more than the pairing saves
    if num_tiles >= _PAIR_TILES or (
        num_tiles >= _PAIR_TILES_WIDE and inp.element_size() == 4
    ):
        unroll = 2
    else:
        unroll = 1
    grid = (min(_NUM_SPC, triton.cdiv(num_tiles, unroll)),)
    if k_norm == 1:
        kernel = _rot90_k1_tile_kernel
    elif k_norm == 2:
        kernel = _rot90_k2_tile_kernel
    else:
        kernel = _rot90_k3_tile_kernel
    with torch_device_fn.device(inp.device):
        kernel[grid](
            inp,
            out,
            M,
            N,
            num_c_tiles,
            num_tiles,
            BLOCK_R=block_r,
            BLOCK_C=block_c,
            U=unroll,
            num_warps=_TILE_WARPS,
        )


def rot90_2d(inp, k, dims, out):
    """Handle the case when dims = [0, 1] with size-dispatched kernels."""
    M = inp.shape[dims[0]]
    N = inp.shape[dims[1]]
    n_elements = out.numel()
    if n_elements == 0:
        return

    # Normalize k to 0, 1, 2, 3
    k_norm = ((k % 4) + 4) % 4

    if k_norm == 0:
        grid = (min(_NUM_SPC, triton.cdiv(n_elements, _FLAT_COPY_BLOCK)),)
        with torch_device_fn.device(inp.device):
            _rot90_flat_copy_kernel[grid](
                inp,
                out,
                n_elements,
                BLOCK=_FLAT_COPY_BLOCK,
                EVEN=n_elements % _FLAT_COPY_BLOCK == 0,
                num_warps=4,
            )
        return

    if n_elements <= _SMALL_NUMEL:
        grid = lambda META: (triton.cdiv(n_elements, META["BLOCK_SIZE"]),)
        with torch_device_fn.device(inp.device):
            rot90_kernel_2d[grid](inp, out, n_elements, M, N, k_norm)
    else:
        _launch_tiled(inp, out, k_norm, M, N)


def rot90(input, k=1, dims=[0, 1]):
    """
    Rotate an n-D tensor by 90 degrees in the plane specified by dims.

    Args:
        input: the input tensor
        k: number of times to rotate (default: 1)
        dims: axis to rotate (default: [0, 1])

    Returns:
        Rotated tensor
    """
    logger.debug("GEMS_ENFLAME ROT90")
    x = input
    if not x.is_contiguous():
        x = x.contiguous()

    dim0, dim1 = dims[0], dims[1]
    M = x.shape[dim0]
    N = x.shape[dim1]

    # Normalize k to 0, 1, 2, 3
    k_norm = ((k % 4) + 4) % 4

    # For k=0 or k=2, output shape is same as input
    # For k=1 or k=3, output dims are swapped
    if k_norm == 0 or k_norm == 2:
        out_shape = list(x.shape)
    else:
        out_shape = list(x.shape)
        out_shape[dim0] = N
        out_shape[dim1] = M

    out = torch.empty(out_shape, device=x.device, dtype=x.dtype)

    if dim0 == 0 and dim1 == 1:
        # Direct path for dims = [0, 1]
        rot90_2d(x, k, dims, out)
    else:
        # General case: transpose to bring dims to [0, 1], rotate, transpose back
        ndim = x.ndim

        # Build permutation to move dims[0] and dims[1] to front
        perm = [dim0, dim1]
        for i in range(ndim):
            if i != dim0 and i != dim1:
                perm.append(i)

        # Inverse permutation to restore original order
        inverse_perm = [0] * ndim
        inverse_perm[dim0] = 0
        inverse_perm[dim1] = 1
        idx = 2
        for i in range(ndim):
            if i != dim0 and i != dim1:
                inverse_perm[i] = idx
                idx += 1

        # Transpose, rotate 2D plane, transpose back
        x_transposed = x.permute(perm)
        out_transposed = torch.empty(out_shape, device=x.device, dtype=x.dtype)
        rot90_2d(x_transposed, k, [0, 1], out_transposed)
        out.copy_(out_transposed.permute(inverse_perm))

    return out
